(defn assign-clusters "Assign each data point to the index of its nearest centroid.\n\n>>> data = np.array([[0.0, 0.0], [0.0, 1.0], [10.0, 10.0], [10.0, 11.0]])\n>>> centroids = np.array([[0.0, 0.0], [10.0, 10.0]])\n>>> assign_clusters(data, centroids).tolist()\n[0, 0, 1, 1]"
  [& _args]
  ;; stub: original requires np,numpy-attr:argmin; pure-Clojure port not applicable
  (throw (ex-info "requires np,numpy-attr:argmin" {:type :UnsupportedOperation})))

(defn revise-centroids "Recompute each centroid as the mean of the points assigned to it.\n\n>>> data = np.array([[0.0, 0.0], [0.0, 1.0], [10.0, 10.0], [10.0, 11.0]])\n>>> assignment = np.array([0, 0, 1, 1])\n>>> revise_centroids(data, 2, assignment).tolist()\n[[0.0, 0.5], [10.0, 10.5]]"
  [& _args]
  ;; stub: original requires np,numpy-attr:mean; pure-Clojure port not applicable
  (throw (ex-info "requires np,numpy-attr:mean" {:type :UnsupportedOperation})))

(defn compute-heterogeneity "Sum of squared distances from each point to its assigned centroid.\n\nThis is the objective k-means minimises; lower is a tighter clustering.\n\n>>> data = np.array([[0.0, 0.0], [0.0, 1.0], [10.0, 10.0], [10.0, 11.0]])\n>>> centroids = np.array([[0.0, 0.5], [10.0, 10.5]])\n>>> assignment = np.array([0, 0, 1, 1])\n>>> float(compute_heterogeneity(data, 2, centroids, assignment))\n1.0"
  [& _args]
  ;; stub: original requires np,numpy-attr:shape,numpy-attr:sum,pairwise_distances; pure-Clojure port not applicable
  (throw (ex-info "requires np,numpy-attr:shape,numpy-attr:sum,pairwise_distances" {:type :UnsupportedOperation})))

