(defn kmeans "Runs k-means on given data and initial set of centroids.\nmaxiter: maximum number of iterations to run.(default=500)\nrecord_heterogeneity: (optional) a list, to store the history of heterogeneity\n                      as function of iterations\n                      if None, do not store the history.\nverbose: if True, print how many data points changed their cluster labels in\n                      each iteration\n\n>>> data = np.array([[0.0, 0.0], [0.0, 1.0], [10.0, 10.0], [10.0, 11.0]])\n>>> initial_centroids = np.array([[0.0, 0.0], [10.0, 10.0]])\n>>> centroids, assignment = kmeans(data, 2, initial_centroids, maxiter=10)\n>>> centroids.tolist()\n[[0.0, 0.5], [10.0, 10.5]]\n>>> assignment.tolist()\n[0, 0, 1, 1]"
  [& _args]
  ;; stub: original requires np,numpy-attr:all,numpy-attr:sum; pure-Clojure port not applicable
  (throw (ex-info "requires np,numpy-attr:all,numpy-attr:sum" {:type :UnsupportedOperation})))

(defn report-generator "Generate a clustering report given these two arguments:\n    predicted - dataframe with predicted cluster column\n    fill_missing_report - dictionary of rules on how we are going to fill in missing\n    values for final generated report (not included in modelling);\n>>> predicted = pd.DataFrame()\n>>> predicted['numbers'] = [1, 2, 3]\n>>> predicted['col1'] = [0.5, 2.5, 4.5]\n>>> predicted['col2'] = [100, 200, 300]\n>>> predicted['col3'] = [10, 20, 30]\n>>> predicted['Cluster'] = [1, 1, 2]\n>>> report_generator(predicted, ['col1', 'col2'], 0)\n           Features               Type   Mark           1           2\n0    # of Customers        ClusterSize  False    2.000000    1.000000\n1    % of Customers  ClusterProportion  False    0.666667    0.333333\n2              col1    mean_with_zeros   True    1.500000    4.500000\n3              col2    mean_with_zeros   True  150.000000  300.000000\n4           numbers    mean_with_zeros  False    1.500000    3.000000\n..              ...                ...    ...         ...         ...\n99            dummy                 5%  False    1.000000    1.000000\n100           dummy                95%  False    1.000000    1.000000\n101           dummy              stdev  False    0.000000         NaN\n102           dummy               mode  False    1.000000    1.000000\n103           dummy             median  False    1.000000    1.000000\n<BLANKLINE>\n[104 rows x 5 columns]"
  [& _args]
  ;; stub: original requires np,numpy-attr:T,numpy-attr:copy,numpy-attr:max,numpy-attr:mean,numpy-attr:min,numpy-attr:std,numpy-attr:sum,numpy-attr:tolist,pd; pure-Clojure port not applicable
  (throw (ex-info "requires np,numpy-attr:T,numpy-attr:copy,numpy-attr:max,numpy-attr:mean,numpy-attr:min,numpy-attr:std,numpy-attr:sum,numpy-attr:tolist,pd" {:type :UnsupportedOperation})))

